'use strict';
(()=>{
 const $=s=>document.querySelector(s);
 const link=document.createElement('link');link.rel='stylesheet';link.href='ai-builder.css?v=20261126.1';document.head.append(link);
 const main=document.querySelector('main');
 const panel=document.createElement('section');panel.id='aiBuilder';panel.className='ai-builder';panel.setAttribute('aria-label','AI circuit builder');
 panel.innerHTML=`<div class="ai-heading"><div class="ai-title"><span class="ai-spark">✳</span><span><strong>AI circuit builder</strong><small id="aiState">Enter your API key to start</small></span></div><details class="ai-key" open><summary id="aiKeySummary">Set API key</summary><div class="ai-key-popover"><label for="aiKey">OpenAI API key</label><div class="ai-key-row"><input id="aiKey" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your API key"><button type="button" id="aiSaveKey" class="primary">Use key</button><button type="button" id="aiClearKey" class="ai-clear-key" hidden>Clear</button></div><p>The key is sent over HTTPS to this project's server for your request. It stays in this tab's memory and is not saved by the app.</p></div></details></div><div id="aiMessages" class="ai-messages" aria-live="polite"><div class="ai-message assistant">Enter your API key to begin. Then describe a circuit and I’ll add supported parts and compatible connections to your canvas.</div></div><form id="aiForm" class="ai-form"><label class="sr-only" for="aiPrompt">Describe a circuit idea</label><textarea id="aiPrompt" rows="1" maxlength="1200" placeholder="e.g. Make an ESP8266 blink an LED…" required></textarea><button id="aiSend" class="primary" type="submit" aria-label="Build this idea">Build <span>↗</span></button></form><div class="ai-note">AI can make mistakes. Check the inspector and real part ratings before wiring hardware.</div>`;
 main.append(panel);
 const keyInput=$('#aiKey'),keyStatus=$('#aiState'),keySave=$('#aiSaveKey'),keyClear=$('#aiClearKey'),keySummary=$('#aiKeySummary'),form=$('#aiForm'),prompt=$('#aiPrompt'),send=$('#aiSend'),messages=$('#aiMessages');
 let apiKey='',busy=false,history=[];
 const catalog=[['mcu','Virtual MCU'],['esp8266','NodeMCU ESP8266'],['battery','Battery packs'],['motorDriver','TB6612FNG motor driver'],['ultrasonic','HC-SR04 distance sensor'],['led','Kingbright WP7113ID red LED'],['motor','Pololu #1101 6 V gearmotor'],['servo','TowerPro SG90 analog servo']].map(([type,label])=>({type,label,pins:RobotModel.pins({boards:[]},{type}).map((p,pin)=>({pin,name:p.name,kind:p.kind})).filter(p=>p.kind!=='reserved')}));
 function addMessage(role,text,sources=[]){const el=document.createElement('div');el.className=`ai-message ${role}`;el.textContent=text;messages.append(el);if(role==='assistant'&&sources.length){const refs=document.createElement('div');refs.className='ai-sources';const label=document.createElement('strong');label.textContent='Research sources';refs.append(label);for(const source of sources.slice(0,5)){if(!source||typeof source.url!=='string'||!/^https:\/\//.test(source.url))continue;const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title||new URL(source.url).hostname;refs.append(a)}if(refs.childElementCount>1)messages.append(refs)}messages.scrollTop=messages.scrollHeight}
 function setKey(){apiKey=keyInput.value.trim();if(!apiKey){keyStatus.textContent='Add an OpenAI API key to start';return}keyStatus.textContent='AI ready · OpenAI API';keySummary.textContent='API key set';keyClear.hidden=false;keyInput.value='';$('#aiKey').placeholder='Key is held in memory';panel.classList.add('ai-ready')}
 keySave.onclick=()=>{setKey();if(apiKey)$('#aiKey').closest('details').open=false};
 keyClear.onclick=()=>{apiKey='';keyInput.value='';keyStatus.textContent='Add an OpenAI API key to start';keySummary.textContent='Set API key';keyClear.hidden=true;panel.classList.remove('ai-ready')};
 function currentState(){return {components:window.CanvasAI.current(),catalog,batteryPacks:['eneloop2','eneloop4','pro4','energizer4','nineVolt'],connectionRules:'Only output-to-input, positive supply-to-power-input, and ground-to-ground connections are allowed.'}}
 async function ask(idea){
  const endpoint=window.CANVAS_AI_ENDPOINT||'/api/build';
  const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey,idea,context:currentState(),history:history.slice(-8)})});
  let data;try{data=await response.json()}catch{throw Error(response.status===404?'No AI server is deployed at this site. Deploy the project server or configure its HTTPS URL in dist/ai-config.js.':'The project server returned an unreadable response.')}
  if(!response.ok)throw Error(data?.error||`The project server could not complete this request (${response.status}).`);
  if(!data?.plan)throw Error('The project server did not return a build plan. Try describing the circuit more simply.');
  const applied=window.CanvasAI.apply(data.plan);return {summary:data.plan.summary, ...applied,sources:Array.isArray(data.sources)?data.sources:[]};
 }
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;const idea=prompt.value.trim();if(!idea)return;if(!apiKey){$('#aiKey').closest('details').open=true;keyInput.focus();addMessage('assistant','Add your OpenAI API key in “Set API key” to build from a description.');return}
  prompt.value='';addMessage('user',idea);busy=true;send.disabled=true;send.textContent='Building…';keyStatus.textContent='Thinking and checking connections…';
  try{const result=await ask(idea);const parts=result.added?`${result.added} part${result.added===1?'':'s'}`:'existing parts';const wires=result.connected?` and ${result.connected} connection${result.connected===1?'':'s'}`:'';const note=`${result.summary||'Build added.'} Added ${parts}${wires}. Press Run simulation when you’re ready.`;addMessage('assistant',note,result.sources);history.push({role:'user',content:idea},{role:'assistant',content:note});history=history.slice(-12);keyStatus.textContent='AI ready · Project server'}catch(err){addMessage('assistant',`I couldn’t build that yet: ${err.message}`);keyStatus.textContent='AI ready · Project server'}finally{busy=false;send.disabled=false;send.innerHTML='Build <span>↗</span>';prompt.focus()}
 };
 prompt.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}});
})();
